20	 * ~/.claude/plans/i-have-now-reference-radiant-salamander.md. Sections
21	 * A-D/F/G of the full design need labelled-data volume/infrastructure this
22	 * app doesn't have yet; this page covers only what the current fixtures
23	 * (a labelled reference fight scored against a re-uploaded, AI-processed
24	 * copy of itself) can honestly show — E0/E1/E2/E8.
25	 */
26	export default function PipelineAccuracy() {
27	  const width = useWindowWidth();
28	  const isMobile = width < 640;
29	
30	  const [fixtures, setFixtures] = useState<FixtureSummary[]>([]);
31	  const [fights, setFights] = useState<Fight[]>([]);
32	  const [selectedId, setSelectedId] = useState<number | null>(null);
33	  const [runs, setRuns] = useState<EvalRunSummary[]>([]);
34	  const [report, setReport] = useState<EvalReport | null>(null);
35	  const [loading, setLoading] = useState(true);
36	  const [error, setError] = useState<string | null>(null);
37	
38	  const loadFixtures = useCallback(() => {
39	    setLoading(true);
40	    Promise.all([fetchFixtures(), fetchFights()])
41	      .then(([fx, fl]) => {
42	        setFixtures(fx);
43	        setFights(fl);
44	        setSelectedId((prev) => {
45	          if (prev !== null && fx.some((f) => f.reference_fight_id === prev)) return prev;
46	          const measurable = fx.find((f) => f.is_measurable);
47	          return (measurable ?? fx[0])?.reference_fight_id ?? null;
48	        });
49	      })
50	      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'))
51	      .finally(() => setLoading(false));
52	  }, []);
53	
54	  useEffect(() => { loadFixtures(); }, [loadFixtures]);
55	
56	  const selected = fixtures.find((f) => f.reference_fight_id === selectedId) ?? null;
57	
58	  useEffect(() => {
59	    if (!selected || !selected.is_measurable) {
60	      setRuns([]);
61	      setReport(null);
62	      return;
63	    }
64	    fetchEvalRuns(selected.reference_fight_id)
65	      .then(setRuns)
66	      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'));
67	  }, [selected]);
68	
69	  useEffect(() => {
70	    if (runs.length === 0) {
71	      setReport(null);
72	      return;
73	    }
74	    fetchEvalRun(runs[runs.length - 1].id)
75	      .then((r) => setReport(r.report))
76	      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'));
77	  }, [runs]);
78	
79	  const candidates = fights.filter((f) => f.purpose === 'ai_labeled' && f.state === 'completed');
80	
81	  return (
82	    <div style={{ maxWidth: 1440, margin: '0 auto', padding: isMobile ? '14px 13px 60px' : '22px 30px 80px', width: '100%' }}>
83	      <div style={{ marginBottom: 16 }}>
84	        <h1 className="font-display" style={{ fontSize: isMobile ? 30 : 40, lineHeight: 0.94, margin: 0, color: 'var(--text-primary)' }}>
85	          PIPELINE ACCURACY
86	        </h1>
87	        <p style={{ margin: '5px 0 0', fontSize: 12.5, fontWeight: 600, color: 'var(--text-muted)' }}>
88	          Reference fixtures scored against pipeline predictions, across versions
89	        </p>
90	      </div>
91	
92	      {loading && <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Loading…</div>}
93	      {error && <div style={{ fontSize: 13, color: 'var(--red-500)', marginBottom: 14 }}>{error}</div>}
94	
95	      {!loading && fixtures.length === 0 && (
96	        <div className="glass" style={{ padding: '20px 22px', fontSize: 13, color: 'var(--text-muted)' }}>
97	          No labelled reference fixture exists yet. Upload a fight as "Self-annotate → Reference" and
98	          finish labelling it to create one.
99	        </div>
100	      )}
101	
102	      {fixtures.length > 0 && (
103	        <div className="glass" style={{ padding: '20px 22px 22px', marginBottom: 16 }}>
104	          <div className="label" style={{ marginBottom: 12 }}>Fixtures</div>
105	          <FixtureTable fixtures={fixtures} selectedId={selectedId} onSelect={setSelectedId} />
106	        </div>
107	      )}
108	
109	      {selected && (
110	        <div className="glass" style={{ padding: '20px 22px 22px' }}>
111	          {!selected.is_measurable ? (
112	            <NotMeasurable fixture={selected} candidates={candidates} onScored={loadFixtures} />
113	          ) : runs.length > 0 ? (
114	            <>
115	              <div style={{ marginBottom: 16 }}>
116	                <ProvenanceLine run={runs[runs.length - 1]} />
117	              </div>
118	              <div style={{ marginBottom: 20 }}>
119	                <HeadlineF1 runs={runs} />
120	              </div>
121	              <div style={{ marginBottom: 20 }}>
122	                <div className="label" style={{ marginBottom: 11 }}>Accuracy history — this fixture, every version</div>
123	                <VersionTrendChart runs={runs} />
124	              </div>
125	
126	              {report && (
127	                <div style={{ display: 'flex', flexDirection: 'column', gap: 20, paddingTop: 18, borderTop: '1px solid rgba(255,255,255,0.05)' }}>
128	                  <div>
129	                    <div className="label" style={{ marginBottom: 11 }}>Classification — matched strikes only</div>
130	                    <ClassificationBreakdown strikes={report.strikes} />
131	                  </div>
132	
133	                  <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: 20 }}>
134	                    <div>
135	                      <div className="label" style={{ marginBottom: 11 }}>Strike family confusion</div>
136	                      <ConfusionHeatmap confusion={report.strikes.family_confusion} emptyLabel="No specific-family matches yet." />
137	                    </div>
138	                    <div>
139	                      <div className="label" style={{ marginBottom: 11 }}>Timing</div>
140	                      <OffsetDotStrip offsets={report.strikes.matched_offsets} />
141	                    </div>
142	                  </div>
143	
144	                  <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: 20 }}>
145	                    <div>
146	                      <div className="label" style={{ marginBottom: 11 }}>Fight state</div>
147	                      <StateDumbbell state={report.state} />
148	                      <div style={{ marginTop: 12 }}>
149	                        <ConfusionHeatmap confusion={report.state.confusion} emptyLabel="No state frames scored yet." />
150	                      </div>
151	                    </div>
152	                    <div>
153	                      <div className="label" style={{ marginBottom: 11 }}>Rounds</div>
154	                      <RoundsCheck rounds={report.rounds} />
155	                    </div>
