8	 * `offset_jitter_frames` are computed server-side at read time from the
9	 * stored report's raw tp/fp/fn/matched_offsets — mirrors ai/eval/score.py's
10	 * PRF properties, since dataclasses.asdict() doesn't serialise properties.
11	 */
12	export interface EvalRunSummary {
13	  id: number;
14	  reference_fight_id: number;
15	  scored_fight_id: number;
16	  git_sha: string;
17	  constants_sha256: string;
18	  tolerance_secs: number;
