23	  f1: number | null;
24	  precision: number | null;
25	  recall: number | null;
26	  tp: number | null;
27	  fp: number | null;
28	  fn: number | null;
29	  offset_bias_frames: number | null;
30	  offset_jitter_frames: number | null;
31	}
32	
33	/** A ground-truth (label) strike — see ai/eval/schema.py's `Strike`. */
34	export interface LabelStrike {
35	  frame: number;
36	  fighter: 'red' | 'blue';
37	  family: string;
38	  target: string;
39	  landed: boolean | null;
40	}
41	
42	/** A pipeline-predicted strike — `Strike` plus the raw pipeline action
43	 * string (e.g. `jab_head`) — see ai/eval/predictions.py's `PredictedStrike`. */
44	export interface PredictedStrikeItem extends LabelStrike {
45	  action: string;
46	}
47	
48	/** One round's match — see ai/eval/score.py's `RoundScore.matched`:
49	 * [round_num, iou, start_offset_secs, end_offset_secs, seeded]. `seeded`
50	 * true means the label round is unverified (still byte-identical to what it
51	 * was auto-seeded from) — its IoU would be circular, so show that instead. */
52	export type MatchedRound = [number, number, number, number, boolean];
53	
54	/** The full ai/eval/score.py `Report`, as persisted by report_io.save_report
