74	    family_confusion: Record<string, number>;
75	    matched_offsets: number[];
76	    missed: LabelStrike[];
77	    spurious: PredictedStrikeItem[];
78	  };
79	  state: {
80	    frames_scored: number;
81	    frames_correct: number;
82	    confusion: Record<string, number>;
83	    gt_transitions_per_min: number;
84	    pred_transitions_per_min: number;
85	    gt_median_dwell_secs: number;
86	    pred_median_dwell_secs: number;
87	  };
88	  rounds: {
89	    matched: MatchedRound[];
90	    gt_count: number;
91	    pred_count: number;
92	  };
93	}
