     8	const shortDate = (iso: string) =>
     9	  new Date(iso).toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
    10	
    11	/**
    12	 * Section E8 — F1/P/R across pipeline versions for one fixture. A hollow
    13	 * marker means the matching constants changed at that version (compare with
    14	 * care); a dashed vertical rule marks a run scored at a different tolerance
    15	 * from the one before it (not directly comparable — honesty rule 8).
    16	 */
    17	export default function VersionTrendChart({ runs }: VersionTrendChartProps) {
    18	  const W = 640, H = 160, padL = 28, padR = 20, padT = 14, padB = 34;
    19	  const n = runs.length;
    20	  if (n < 1) return null;
    21	
    22	  const x = (i: number) => n === 1 ? W / 2 : padL + (i / (n - 1)) * (W - padL - padR);
    23	  const y = (v: number) => H - padB - (v / 100) * (H - padB - padT);
    24	  const line = (key: 'f1' | 'precision' | 'recall') =>
    25	    runs.map((r, i) => `${i === 0 ? 'M' : 'L'}${x(i).toFixed(1)},${y(r[key] ?? 0).toFixed(1)}`).join(' ');
    26	
    27	  return (
    28	    <div>
    29	      <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={H} preserveAspectRatio="xMidYMid meet" style={{ display: 'block', overflow: 'visible' }}>
    30	        {[0, 25, 50, 75, 100].map((g) => (
    31	          <line key={g} x1={padL} x2={W - padR} y1={y(g)} y2={y(g)} stroke="rgba(255,255,255,0.06)" strokeWidth="1" />
    32	        ))}
    33	        {runs.map((r, i) => (
    34	          i > 0 && r.tolerance_frames !== runs[i - 1].tolerance_frames && (
    35	            <line key={`tol-${r.id}`} x1={x(i)} x2={x(i)} y1={padT} y2={H - padB}
    36	              stroke="rgba(250,178,25,0.5)" strokeWidth="1" strokeDasharray="3 3" />
    37	          )
    38	        ))}
    39	        <path d={line('precision')} fill="none" stroke="rgba(0,218,243,0.3)" strokeWidth="1.5" strokeDasharray="3 3" />
    40	        <path d={line('recall')} fill="none" stroke="rgba(179,157,251,0.5)" strokeWidth="1.5" strokeDasharray="3 3" />
    41	        <path d={line('f1')} fill="none" stroke="var(--cyan-400)" strokeWidth="2" />
    42	        {runs.map((r, i) => {
    43	          const constantsChanged = i > 0 && r.constants_sha256 !== runs[i - 1].constants_sha256;
    44	          return (
