    47	              stroke="var(--cyan-400)" strokeWidth={i === n - 1 ? 2.5 : 1.5}>
    48	              <title>{r.git_sha.slice(0, 7)} · {shortDate(r.generated_at)} · F1 {r.f1}% · P {r.precision}% · R {r.recall}%{constantsChanged ? ' · constants changed' : ''}</title>
    49	            </circle>
    50	          );
    51	        })}
    52	      </svg>
    53	      <div style={{ position: 'relative', height: 34, marginTop: 2 }}>
    54	        {runs.map((r, i) => (
    55	          <div key={r.id} style={{
    56	            position: 'absolute', top: 0, left: `${(x(i) / W) * 100}%`, transform: 'translateX(-50%)',
    57	            textAlign: 'center', whiteSpace: 'nowrap',
    58	          }}>
    59	            <div style={{ fontFamily: 'ui-monospace,Menlo,monospace', fontSize: 10, fontWeight: 700, color: i === n - 1 ? '#9fe8f4' : 'var(--text-muted)' }}>
